const $ = (q, root=document) => root.querySelector(q);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub = n => new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(n/100)+' ₽';
const money = n => {
  const raw=String(n ?? '').trim().replace(/[\s\u00a0\u202f]/g,'').replace(/₽$/,'');
  if(!/^\d+(?:[.,]\d{1,2})?$/.test(raw))throw Error('Введите сумму, например 2 000 или 2 000,50.');
  const v=Number(raw.replace(',','.'));
  if(!Number.isFinite(v)||!Number.isSafeInteger(Math.round(v*100)))throw Error('Укажите корректную сумму.');
  return Math.round(v*100);
};
let features={},serverDay=null,closingPreview=null,renderedDay=null;
const supported=name=>!window.KOPIT_SUPABASE||features[name]===true;
const pendingMonth=()=>supported('manual_month_close')&&state.manual_month_close&&state.month<(serverDay||dateKey()).slice(0,7);
let pageFlow=null;
let state, revision, email, page='home', authMode='login';
const app=$('#app'), modal=$('#modal');
const dateNow=()=>new Date(new Date().toLocaleString('en-US',{timeZone:'Europe/Moscow'}));
const dateKey=()=>{const d=dateNow();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
async function api(path,data){if(window.KOPIT_SUPABASE){try{return await cloudApi(path,data);}catch(e){if(e.status===409)await load();if(e.status===401&&path==='action')auth();throw e;}}if(window.KOPIT_DEMO)return demoApi(path,data);const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let body;try{body=await response.json();}catch{throw Error('Сервер недоступен. Проверьте подключение.');}if(!response.ok){if(response.status===409)await load();if(response.status===401&&path==='action')auth();throw Error(body.error||'Не удалось выполнить действие.');}return body;}
function accept(data){if(state&&data.revision<revision)return;state=data.state;revision=data.revision;email=data.email;features=data.features||{};serverDay=data.server_date||null;closingPreview=data.month_close_preview||null;}
async function load(renderPage=true){try{accept(await api('state'));if(renderPage)render();if(!window.KOPIT_DEMO)$('#logout').classList.remove('hidden');}catch(e){if(e.code==='recovery_required'){authMode='password';auth();}else if(e.status===401||(!window.KOPIT_SUPABASE&&!state))auth();else if(!state){app.innerHTML=`<section class="auth"><h1>Подключение</h1><p role="alert">${esc(e.message)}</p><button id="retry" class="primary">Повторить</button></section>`;$('#retry').onclick=()=>load();}else toast(e.message);}}
const members=()=>state?.household?.members||[];
const memberDeviceKey=()=>`kopit-member:${window.KOPIT_SUPABASE_CONFIG?.url||location.origin}:${location.pathname}:${email}`;
function activeMember(){let id;try{id=localStorage.getItem(memberDeviceKey());}catch{}return members().find(m=>m.id===id)||(members().length===1?members()[0]:null);}
function ensureMember(){if(!supported('household')||!members().length||activeMember())return true;goPage('members');toast('Выберите, кто пользуется этим устройством.');return false;}
function memberNote(){return members().length?`<p class="member-note">Участник: <strong>${esc(activeMember()?.name||'не выбран')}</strong><br><span class="muted">Все расходы — из общего бюджета.</span></p>`:'';}
function goalOwner(g){const id=state.household?.owners?.[g.id];return id?members().find(m=>m.id===id)?.name||'Личная цель':'Общая цель';}
function ownerField(g){return supported('household')&&members().length?`<label for="goal-owner">Для кого цель</label><select id="goal-owner"><option value="">Общая цель</option>${members().map(m=>`<option value="${m.id}" ${state.household?.owners?.[g?.id]===m.id?'selected':''}>${esc(m.name)} — личная</option>`).join('')}</select><p class="muted">Все цели пополняются из общих свободных денег и видны всем участникам.</p>`:'';}
function memberForm(member){const first=!members().length;open(member?'Имя участника':'Добавить участника',`<label for="member-name">Имя</label><input id="member-name" maxlength="60" required value="${esc(member?.name||'')}" autocomplete="off"><p class="muted">Это профиль внутри общего аккаунта. Отдельная почта и пароль не нужны.</p>`,async()=>{await action('household_member',{...(member?{id:member.id}:{}),name:$('#member-name').value.trim()});if(first){try{localStorage.setItem(memberDeviceKey(),members().at(-1).id);}catch{}}goPage('members');});}
function householdSettings(){
 $('#content').innerHTML=`<h1>Участники</h1><p class="muted">Один аккаунт, общий бюджет и общие деньги для всех целей. Список участников доступен на всех устройствах.</p>${members().length?`<section class="card"><label for="device-member">Кто пользуется этим устройством</label><select id="device-member"><option value="">Выберите участника</option>${members().map(m=>`<option value="${m.id}" ${activeMember()?.id===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><p class="muted" id="member-device-status" role="status">Выбор запоминается только в этом браузере. На другом устройстве можно выбрать другого участника.</p></section>`:'<p class="empty">Добавьте первого участника, чтобы отмечать его доходы и расходы.</p>'}<div class="member-list">${members().map(m=>`<div class="row"><strong>${esc(m.name)}</strong><button class="quiet" data-edit-member="${m.id}">Изменить имя</button></div>`).join('')}</div><button id="add-member" class="primary">+ Добавить участника</button><p class="muted">Старые операции остаются без участника. Личные цели видны всем, кто вошёл по общей почте.</p>`;
 $('#add-member').onclick=()=>memberForm();document.querySelectorAll('[data-edit-member]').forEach(b=>b.onclick=()=>memberForm(members().find(m=>m.id===b.dataset.editMember)));
 if($('#device-member'))$('#device-member').onchange=()=>{try{const value=$('#device-member').value;if(value)localStorage.setItem(memberDeviceKey(),value);else localStorage.removeItem(memberDeviceKey());$('#member-device-status').textContent=value?'Участник сохранён для этого устройства.':'Выберите участника перед записью расходов.';}catch{$('#member-device-status').textContent='Браузер не разрешил сохранить выбор.';}};
}
function actorMatches(t){const selected=$('#history-member')?.value||'';return !selected||(state.household?.actors?.[t.id]||'unassigned')===selected;}
async function action(type,data){if(supported('household')&&members().length&&['income','expense','daily_expenses','opening_details','allocate','goal_expense','closing_reserve'].includes(type)){if(!activeMember())throw Error('Выберите участника в настройках.');data={...data,actor_id:activeMember().id};}const result=await api('action',{...data,action:type,revision});accept(result);render();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.add('hidden'),4500);}
function auth(){
 $('#header-tools')?.remove();
 pageFlow=null;setupDraft=null;setupBack=[];state=null;revision=undefined;email=undefined;$('#logout').classList.add('hidden');
 const recovery=authMode==='recover',password=authMode==='password',register=authMode==='register';
 app.innerHTML=`<section class="auth"><div class="eyebrow">Копит / личный учёт</div><h1>${password?'Новый пароль':recovery?'Восстановить доступ':register?'Создать аккаунт':'Войти в Копит'}</h1><p class="muted">Месячный бюджет, резерв и накопления. Ваши записи доступны с разных устройств после входа.</p><form id="auth-form">${password?'':'<label for="email">Электронная почта</label><input id="email" type="email" autocomplete="email" required maxlength="254">'}${recovery?'':`<label for="password">Пароль</label><input id="password" type="password" autocomplete="${register||password?'new-password':'current-password'}" minlength="8" maxlength="200" required>`}<p id="form-error" role="alert"></p><button class="primary">${password?'Сохранить пароль':recovery?'Отправить ссылку':register?'Создать аккаунт':'Войти'}</button></form><button id="auth-toggle" class="quiet">${register||recovery||password?'Вернуться ко входу':'Первый раз здесь? Создать аккаунт'}</button>${window.KOPIT_SUPABASE&&!recovery&&!password?'<button id="recover" class="quiet">Забыли пароль?</button>':''}<div class="note">Начальный бюджет — 175 000 ₽. Его можно изменить в настройках.</div></section>`;
 $('#auth-toggle').onclick=()=>{authMode=register||recovery||password?'login':'register';auth();};if($('#recover'))$('#recover').onclick=()=>{authMode='recover';auth();};
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const b=$('button.primary');b.disabled=true;try{const result=await api(authMode,{email:$('#email')?.value,password:$('#password')?.value});if(result.confirmation_required||recovery){$('#form-error').textContent=result.confirmation_required?'Откройте письмо и подтвердите почту. После этого войдите.':'Если аккаунт существует, на почту придёт ссылка для восстановления.';b.disabled=false;return;}authMode='login';await load();}catch(err){$('#form-error').textContent=err.message;b.disabled=false;}};
}
function progress(value,total){return `<div class="progress"><progress max="${Math.max(1,total)}" value="${Math.max(0,Math.min(value,total))}" aria-label="Накоплено ${esc(rub(value))} из ${esc(rub(total))}"></progress></div>`;}
const monthSpent=()=>((state.opening?.month===state.month?state.opening.spent:0)||0)+state.transactions.filter(t=>t.kind==='expense'&&t.date.startsWith(state.month)).reduce((a,t)=>a+t.amount,0);
