Object.assign(iconPaths,{"edit":"<path d=\"M21.174 6.812a1 1 0 0 0-3.986-3.987L3.842 16.174a2 2 0 0 0-.5.83l-1.321 4.352a.5.5 0 0 0 .623.622l4.353-1.32a2 2 0 0 0 .83-.497z\"/><path d=\"m15 5 4 4\"/>","diary":"<path d=\"M13.4 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7.4\"/><path d=\"M2 6h4\"/><path d=\"M2 10h4\"/><path d=\"M2 14h4\"/><path d=\"M2 18h4\"/><path d=\"M21.378 5.626a1 1 0 1 0-3.004-3.004l-5.01 5.012a2 2 0 0 0-.506.854l-.837 2.87a.5.5 0 0 0 .62.62l2.87-.837a2 2 0 0 0 .854-.506z\"/>"});
const iconGroups=[["Быт", [["shopping-basket", "Продукты"], ["utensils", "Еда"], ["coffee", "Кофе"], ["pizza", "Пицца"], ["apple", "Фрукты"], ["wine", "Напитки"], ["house", "Дом"], ["key-round", "Аренда"], ["sofa", "Мебель"], ["lamp", "Освещение"], ["plug", "Коммунальные"], ["droplets", "Вода"], ["washing-machine", "Техника"], ["spray-can", "Уборка"], ["cooking-pot", "Кухня"]]], ["В пути", [["car", "Машина"], ["bus", "Автобус"], ["train-front", "Поезд"], ["bike", "Велосипед"], ["plane", "Самолёт"], ["fuel", "Топливо"], ["parking-circle", "Парковка"], ["ship", "Корабль"], ["map-pin", "Место"], ["luggage", "Багаж"], ["ticket", "Билеты"], ["hotel", "Отель"], ["tent", "Кемпинг"], ["compass", "Походы"], ["footprints", "Прогулки"]]], ["Для себя", [["heart-pulse", "Здоровье"], ["pill", "Аптека"], ["stethoscope", "Врач"], ["dumbbell", "Спорт"], ["shirt", "Одежда"], ["scissors", "Стрижка"], ["sparkles", "Уход"], ["book-open", "Книги"], ["graduation-cap", "Образование"], ["languages", "Языки"], ["music", "Музыка"], ["clapperboard", "Кино"], ["gamepad-2", "Игры"], ["palette", "Творчество"], ["camera", "Фотография"]]], ["Другое", [["smartphone", "Телефон"], ["laptop", "Компьютер"], ["wifi", "Интернет"], ["headphones", "Наушники"], ["briefcase-business", "Работа"], ["wrench", "Ремонт"], ["hammer", "Инструменты"], ["gift", "Подарки"], ["baby", "Дети"], ["paw-print", "Питомцы"], ["flower-2", "Цветы"], ["hand-heart", "Помощь"], ["receipt", "Счета"], ["landmark", "Налоги"], ["ellipsis", "Прочее"]]]];
const categoryIconLabels=Object.fromEntries(iconGroups.flatMap(g=>g[1]));

function pictogram(name,extra=''){return `<svg class="pictogram ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.star}</svg>`;}
function itemIcon(item){if(item?.icon)return item.icon;const name=(item?.name||'').toLowerCase();if(/запас|резерв/.test(name))return 'reserve';if(/жиль|дом|аренд/.test(name))return 'home';if(/еда|кафе|продукт/.test(name))return 'coffee';if(/машин|авто/.test(name))return 'car';if(/отпуск|путеш/.test(name))return 'plane';if(/ноут|техник/.test(name))return 'laptop';if(/здоров|себя/.test(name))return 'heart';return 'star';}
function iconPicker(item){const chosen=itemIcon(item),group=Math.max(0,iconGroups.findIndex(g=>g[1].some(([id])=>id===chosen)));return `<fieldset class="icon-picker"><legend>Пиктограмма</legend><input id="icon-choice" type="hidden" value="${esc(chosen)}"><div class="icon-groups" role="group" aria-label="Группы пиктограмм">${iconGroups.map(([name],i)=>`<button type="button" data-icon-group="${i}" aria-pressed="${i===group}">${name}</button>`).join('')}</div>${iconGroups.map(([,items],i)=>`<div class="icon-grid" data-icon-panel="${i}" ${i===group?'':'hidden'}>${items.map(([id,name])=>`<button type="button" data-icon-choice="${id}" aria-label="${name}" aria-pressed="${chosen===id}" class="${chosen===id?'selected':''}">${pictogram(id)}</button>`).join('')}</div>`).join('')}<p class="muted">60 пиктограмм · единый контурный стиль</p></fieldset>`;}
function littleHuman(){return `<svg class="little-human" viewBox="0 0 240 180" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="124" cy="38" r="18" fill="#f1e76b"/><path d="M110 29c5-13 25-12 31 2M117 39h1m13 0h1m-12 6c4 4 8 4 12 0M110 56l-12 12-5 33 32 12 29-12-8-33-13-12M101 69 70 91 47 75m99-6 27 24 21-21M110 107l-31 27c-13 8-15 18 5 20l42-16 37 17c17 0 18-12 4-20l-28-29M46 74l-4-9m4 9 8-7m141 4 3-10m-3 10-8-6M118 70v17h12V70M32 156h172"/><circle cx="42" cy="47" r="19"/><path d="M36 47h12m-6-6v12M186 34h26v25h-26zM190 29h18M189 44h20M196 49h6m-14 61 4-7 4 7 8 1-6 5 2 8-8-4-7 4 1-8-6-5 8-1"/></svg>`;}
function tutorial(){
  const steps=[
    {n:'00',title:'Начните с фактических денег',text:'При первом входе задайте бюджет на месяц, укажите уже потраченное и сколько денег действительно есть. Разделите их на остаток текущего месяца и резерв. Накопления целей укажите отдельно, не учитывая их повторно в общей сумме. Категории и их лимиты необязательны. Проверьте итог и нажмите «Сохранить и начать»: стартовые остатки сохранятся вместе, без фиктивных доходов и расходов.',image:'tutorial-setup.png',alt:'Первоначальная настройка: месячный бюджет',caption:'Первый вход → пошаговая настройка',button:'Открыть настройки',page:'settings'},
    {n:'01',title:'Смотрите, сколько осталось на месяц',text:'На главной крупно показан остаток, ниже — ориентиры на неделю и день. Это подсказки на оставшиеся дни, а не дополнительные деньги. Резерв и свободные деньги показаны отдельно. Ниже — расходы по категориям, месячные лимиты и сколько осталось. Цели и распределение находятся во вкладке «Цели». Бюджет можно изменить в настройках: меняется план, сами остатки не перекладываются. При перерасходе сумма показывается с минусом; деньги из целей автоматически не забираются.',image:'tutorial-budget.png',alt:'Главная с остатком, резервом и месячными лимитами категорий',caption:'Обзор → деньги на первом месте',button:'Открыть обзор',page:'home'},
    {n:'02',title:'Записывайте каждое поступление',text:'Нажмите «+ Доход» на главной и введите сумму. Доход сначала покрывает перерасход и нехватку текущего месячного бюджета, затем пополняет резерв до одного месячного бюджета. Оставшаяся часть появляется в строке «Доступно для целей». Например: бюджет 100 000 ₽, остаток 60 000 ₽, уже потрачено 40 000 ₽, резерв 70 000 ₽. Из нового дохода 80 000 ₽ в резерв пойдёт 30 000 ₽, а свободными станут 50 000 ₽.',image:'tutorial-income.png',alt:'Нижнее окно добавления дохода с одним полем суммы',caption:'Обзор → + Доход',button:'Вернуться в обзор',page:'home'},
    {n:'03',title:'Записывайте расходы в своих категориях',text:'Нажмите «− Расход», укажите сумму, категорию и дату. Сегодня выбрано по умолчанию; доступны даты активного месяца не позднее сегодня. Новую категорию можно создать прямо из формы — сумма и дата сохранятся. Теги необязательны. Категории, пиктограммы и лимиты меняются в настройках; архивную категорию можно вернуть, её прежние записи остаются в истории.',image:'tutorial-expense.png',alt:'Новая форма расхода: сумма, категория и изменяемая дата',caption:'Обзор → − Расход; Настройки → Категории расходов',button:'Открыть категории',page:'categories'},
    {n:'04',title:'Заполняйте дневник несколькими строками',text:'Нажмите иконку блокнота рядом с датой. На отдельной странице «Как прошёл день?» выберите день и нажмите «+ Добавить расход». В каждой строке выберите категорию и введите сумму. Ненужную строку можно убрать. Уже записанные суммы показаны отдельно: повторно вводить их не нужно. Проверьте итог новых расходов. Если за день нет записанных расходов, доступна отметка «Сегодня без расходов». Сохраните весь список одной кнопкой.',image:'tutorial-daily.png',alt:'Дневник расходов с несколькими строками и итоговой суммой',caption:'Иконка дневника рядом с датой → расходы за день',button:'Открыть дневник',flow:true},
    {n:'05',title:'Распределяйте свободные деньги осознанно',text:'Когда обеспечены текущий месяц и резерв следующего, во вкладке «Цели» нажмите «Распределить»: откроется отдельная страница. Ползунки меняют суммы с шагом 500 ₽ и не позволяют превысить доступное. В полях рядом можно ввести точную сумму, включая копейки. Выберите цели или «Резерв будущих зарплат». Нераспределённый остаток меньше 500 ₽ отправится в резерв при сохранении — это показано заранее. Остаток ровно 500 ₽ останется свободным. Резерв может хранить деньги на несколько месяцев.',image:'tutorial-allocation.png',alt:'Актуальное распределение с ползунками, точными суммами и строкой резерва',caption:'Цели → Распределить',button:'Открыть цели',page:'goals'},
    {n:'06',title:'Копите на конкретные цели',text:'Добавьте название цели, нужную сумму, уже накопленное и срок по желанию. Кольцо показывает прогресс; нажмите строку цели, чтобы открыть её карточку, пополнения и историю. Пополнение использует свободные деньги. Достигнутую цель можно завершить, сохранив накопления. Просроченную дату можно перенести или убрать. Изменение «Уже накоплено» у существующей цели требует подтверждения: это корректировка фактических денег, она меняет общий капитал и записывается в журнал.',image:'tutorial-goals.png',alt:'Карточка цели с кольцом прогресса, остатком и историей',caption:'Цели → карточка цели → редактирование',button:'Открыть цели',page:'goals'},
    {n:'07',title:'Исправляйте записи через историю',text:'В «Истории» выберите месяц и нажмите «Изменить» рядом с доходом или расходом. Запись активного месяца можно исправить или удалить; отмена последнего удаления остаётся доступна до завершения месяца, в том числе после перезагрузки. Если доход уже использован, приложение не станет скрыто списывать деньги из целей или делать резерв отрицательным. Для старого дохода без записанного распределения нужна отдельная сверка. Закрытые месяцы доступны для просмотра.',image:'tutorial-history.png',alt:'Актуальная история по дням с суммами и действиями исправления',caption:'История → Изменить → сохранить или удалить',button:'Открыть историю',page:'history'},
    {n:'08',title:'Завершайте месяц вручную',text:'С первого числа нового месяца на главной появляется блок «Завершить месяц». Он остаётся, даже если выйти из сценария. Сначала распределите свободные деньги по целям или отправьте их в резерв. Переносится весь остаток, недостающее берётся из резерва, неиспользованный резерв сохраняется. Если денег не хватает, месяц всё равно начнётся с доступной суммой и предупреждением о дефиците. Пропущенные месяцы закрываются по очереди; повторное нажатие не выполняет тот же переход второй раз.',image:'tutorial-month.png',alt:'Ручное завершение месяца с переносом остатков и отдельными кнопками распределения',caption:'Обзор → Завершить месяц → проверить и перенести',button:'Вернуться в обзор',page:'home'},
    {n:'09',title:'Проверяйте результат сохранения',text:'После подтверждения действия записи сохраняются в аккаунте и доступны на другом устройстве. Если связь прервалась и результат неизвестен, перезагрузите страницу: приложение повторит тот же запрос, а сервер не выполнит его дважды. Проверьте историю, прежде чем создавать новую запись вручную. В демоверсии изменения исчезают после перезагрузки; тестовая версия предназначена для вымышленных данных.',image:'tutorial-reserve.png',alt:'Главная после загрузки с отдельными суммами месяца, резерва и целей',caption:'После сохранения → сверить остатки и историю',button:'Открыть обзор',page:'home'}
  ];
  $('#content').innerHTML=`<section class="tutorial-intro"><span class="eyebrow">Инструкция / бюджет в своём темпе</span><h1>Как пользоваться «Копит»</h1><h2>Суть подхода: зарплата самому себе</h2><p>Доход может приходить нерегулярно, а расходы на жизнь повторяются каждый месяц. Вы выбираете месячный бюджет и отделяете деньги на жизнь от резерва будущих месяцев и накоплений на цели.</p><p>Так вы ориентируетесь на понятную сумму расходов, а не на размер последнего поступления. Бюджет — это план: приложение распределяет только деньги, которые у вас действительно есть.</p><div class="tutorial-principle"><strong>Три отдельных назначения денег</strong><p><b>Остаток месяца</b> — на повседневные расходы до его конца.</p><p><b>Резерв</b> — на будущие месяцы; он может быть больше одной зарплаты.</p><p><b>Цели</b> — отдельные накопления на конкретные покупки и планы.</p></div><p>Новый доход сначала обеспечивает месяц и минимальный резерв. Только оставшуюся свободную сумму вы направляете на цели или дополнительный запас.</p><a class="tutorial-anchor" href="#guide-00">Перейти к пошаговой инструкции ↓</a><details class="tutorial-contents"><summary>Разделы инструкции</summary><ol>${steps.map(s=>`<li><a href="#guide-${s.n}">${s.title}</a></li>`).join('')}</ol></details></section><div class="tutorial-steps">${steps.map((s,i)=>`<article id="guide-${s.n}" class="tutorial-step"><div class="tutorial-text"><span class="eyebrow">${i+1} / ${steps.length}</span><h2>${s.title}</h2><p>${s.text}</p><button class="primary" ${s.flow?'data-guide-flow':`data-guide-page="${s.page}"`}>${s.button} →</button></div><figure><img src="${s.image.startsWith('data:')?s.image:'./'+s.image}" alt="${s.alt}" loading="lazy"><figcaption>${s.caption}</figcaption></figure>${s.n==='03'?'<figure><img src="./tutorial-categories.png" alt="Категории расходов с пиктограммами и лимитами" loading="lazy"><figcaption>Настройки → Категории расходов</figcaption></figure>':s.n==='06'?'<figure><img src="./tutorial-goaledit.png" alt="Редактирование цели со сроком и подтверждением корректировки накоплений" loading="lazy"><figcaption>Карточка цели → редактирование</figcaption></figure>':''}</article>`).join('')}</div><div class="note tutorial-note">Скриншоты показывают текущий интерфейс на вымышленных данных. Напоминания работают, пока приложение открыто и браузер разрешает уведомления.</div>`;
  app.querySelectorAll('[data-guide-page]').forEach(b=>b.onclick=()=>{page=b.dataset.guidePage;render();window.scrollTo(0,0);});
  $('[data-guide-flow]').onclick=()=>{if(pendingMonth()){toast('Сначала завершите предыдущий месяц.');return;}dailyFlow();};
}

function goPage(next){pageFlow=null;page=next;render();window.scrollTo(0,0);}
function render(){
 if(pageFlow&&$('#page-form'))return;
 renderedDay=dateKey();
 if(!state)return;
 $('#header-tools')?.remove();
 if(needsSetup()){if(!setupDraft)startSetup();else drawSetup();return;}
 const header=document.querySelector('.header');
 header.insertAdjacentHTML('beforeend',`<div id="header-tools"><span class="header-date">${dateNow().toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span><button class="icon-button" id="daily-start" aria-label="Расходы за день">${pictogram('diary')}</button><button class="icon-button" id="settings-shortcut" aria-label="Настройки">${pictogram('settings')}</button></div>`);
 $('#daily-start').disabled=!!pendingMonth();$('#daily-start').onclick=dailyFlow;$('#settings-shortcut').onclick=()=>goPage('settings');
 const labels={home:'Обзор',goals:'Цели',history:'История'};
 app.innerHTML=`<div id="content"></div><nav class="bottom-nav" aria-label="Основное меню">${Object.entries(labels).map(([id,name])=>`<button data-page="${id}" ${(pageFlow?.origin||page)===id?'aria-current="page"':''} class="${(pageFlow?.origin||page)===id?'active':''}">${name}</button>`).join('')}</nav>`;
 app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>goPage(b.dataset.page));
 ({home,categories,goals,history:transactionHistory,settings,notifications:notificationSettings,account:accountSettings,members:householdSettings,tutorial,detail:goalDetail,closing:monthClosing})[page]?.();remind();
}
function ring(g,large=false){const percent=Math.max(0,Math.min(100,Math.round(g.saved/g.target*100)));return `<div class="ring ${large?'large-ring':''}" role="img" aria-label="Накоплено ${percent}%"><svg viewBox="0 0 44 44" aria-hidden="true"><circle class="track" cx="22" cy="22" r="18"/><circle class="fill" cx="22" cy="22" r="18" pathLength="100" stroke-dasharray="${percent} 100"/></svg><span>${percent}%</span></div>`;}
let selectedGoal=null,goalOrigin='goals';
function goalRows(){return state.goals.length?state.goals.map(g=>`<button class="goal-row" data-goal-detail="${esc(g.id)}">${ring(g)}<span class="grow"><strong>${esc(g.name)}</strong><small>${esc(goalOwner(g))}</small><small>${rub(g.saved)} из ${rub(g.target)}${g.completed?" · Завершена":""}</small></span><span aria-hidden="true">›</span></button>`).join(''):`<button class="add-row" id="empty-add-goal"><span class="plus-disc" aria-hidden="true">+</span><span><strong>Добавить цель</strong><small>На что хотите накопить?</small></span></button>`;}
function bindGoalRows(){app.querySelectorAll('[data-goal-detail]').forEach(b=>b.onclick=()=>{selectedGoal=b.dataset.goalDetail;goalOrigin=page;goPage('detail');});if($('#empty-add-goal'))$('#empty-add-goal').onclick=()=>goalForm();}
function categorySummary(records,limits=false){
 const groups=new Map();
 if(limits)state.categories.filter(c=>!c.archived).forEach(c=>groups.set(c.id,{id:c.id,name:c.name,icon:itemIcon(c),limit:c.limit,total:0}));
 for(const t of records){const key=t.category||'uncategorized',c=state.categories.find(c=>c.id===key);if(!groups.has(key))groups.set(key,{id:key,name:c?.name||t.category_name||'Без категории',icon:c?itemIcon(c):'categories',limit:c?.limit,total:0});groups.get(key).total+=t.amount;}
 if(!groups.size)return '<p class="empty">Пока нет расходов по категориям.</p>';
 const total=records.reduce((sum,t)=>sum+t.amount,0);
 return [...groups.values()].sort((a,b)=>b.total-a.total).map(c=>`<div class="category-summary-row"><div class="row"><strong class="item-heading"><span class="category-mini" style="${categoryColorStyle(c)}">${pictogram(c.icon)}</span>${esc(c.name)}</strong><strong>${rub(c.total)}</strong></div>${limits?`<small>${c.limit==null?'Лимит не задан':`Лимит ${rub(c.limit)} в месяц · ${c.total>c.limit?'превышен на '+rub(c.total-c.limit):'осталось '+rub(c.limit-c.total)}`}</small>${c.limit>0?`<progress max="${c.limit}" value="${Math.min(c.total,c.limit)}" aria-label="Использовано лимита: ${esc(c.name)}"></progress>`:''}`:`<small>${total?Math.round(c.total/total*100):0}% расходов за период</small>`}</div>`).join('');
}
function spendingStatistics(){
 const end=dateKey(),today=new Date(end+'T12:00:00'),week=new Date(today);week.setDate(today.getDate()-(today.getDay()+6)%7);
 const local=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 const period=$('#stats-period').value,start=period==='week'?local(week):period==='year'?end.slice(0,4)+'-01-01':$('#history-month').value+'-01';
 const finish=period==='month'?$('#history-month').value+'-31':end;
 const records=state.transactions.filter(t=>t.kind==='expense'&&t.date>=start&&t.date<=finish&&actorMatches(t));
 $('#stats-range').textContent=period==='month'?'Выбранный месяц истории':`${start} — ${end}`;
 $('#stats-total').textContent=rub(records.reduce((a,t)=>a+t.amount,0));
 $('#stats-categories').innerHTML=categorySummary(records);
 $('#stats-note').textContent='По подробным расходам из месячного бюджета. Начальные расходы без категории и расходы из целей сюда не входят.';
}
function home(){
 const d=pendingMonth()?new Date(state.month+'-01T12:00:00'):dateNow(),days=new Date(d.getFullYear(),d.getMonth()+1,0).getDate()-d.getDate()+1,weekly=Math.round(Math.max(0,state.balance)/days*Math.min(7,days));
 const month=d.toLocaleDateString('ru-RU',{month:'long'}),next=new Date(d.getFullYear(),d.getMonth()+1,1).toLocaleDateString('ru-RU',{month:'long'}),last=new Date(d.getFullYear(),d.getMonth()+1,0).toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
 $('#content').innerHTML=`<h1>Деньги под рукой</h1>${pendingMonth()?`<section class="note" role="status"><strong>Завершить месяц · ${esc(state.month)}</strong><p>Проверьте распределение и перенесите остатки. До завершения новые доходы и расходы недоступны.</p><button id="close-month-start" class="primary">Завершить месяц</button></section>`:state.manual_month_close&&state.budget-state.balance-monthSpent()>0?`<p class="note" role="status">На бюджет месяца не хватает ${rub(state.budget-state.balance-monthSpent())}. Доступные деньги перенесены; новые доходы сначала покроют нехватку.</p>`:""}<section class="hero ${state.balance<0?'negative':''}"><div class="muted">Осталось на ${month}</div><div class="big">${rub(state.balance).replace('-','−')}</div><p class="muted">из бюджета ${rub(state.budget)} · до ${last}</p>${pendingMonth()?'<p>Остатки прошлого месяца ждут завершения.</p>':state.balance>=0?`<div class="guides"><div><span class="muted">На неделю</span><strong>${rub(weekly)}</strong></div><div><span class="muted">На день</span><strong>${rub(Math.round(state.balance/days))}</strong></div></div>`:'<p>Расходы превысили остаток месяца. Накопления сохраняются.</p><button id="overspent-budget" class="quiet">Изменить бюджет →</button>'}<div class="actions"><button class="primary" id="add-expense">− Расход</button><button id="add-income">+ Доход</button></div></section><div class="row"><span>Отложено на ${next}</span><strong>${rub(state.reserve)}</strong></div><div class="row"><span>Свободно для распределения</span><strong>${rub(state.free)}</strong></div>${!pendingMonth()&&dateNow().getDate()===1&&canAllocate()?'<p class="note">Начался новый месяц. Свободные деньги можно распределить во вкладке «Цели».</p>':''}${!pendingMonth()&&state.closing_audit?.at(-1)?.income<state.budget?`<p class="note">В прошлом месяце заработано ${rub(state.closing_audit.at(-1).income)} — меньше месячного бюджета.${state.budget-state.balance-monthSpent()>0?'':' Прежние остатки покрывают этот месяц.'}</p>`:''}<section class="category-overview"><h2>Расходы по категориям</h2><p class="muted">За ${month} · месячные лимиты</p>${categorySummary(state.transactions.filter(t=>t.kind==='expense'&&t.date.startsWith(state.month)),true)}${state.opening?.month===state.month&&state.opening.spent?`<p class="muted">Ещё ${rub(state.opening.spent)} потрачено до начала подробного учёта, без категории.</p>`:''}</section>`;
 if($('#close-month-start'))$('#close-month-start').onclick=()=>goPage('closing');$('#add-expense').disabled=!!pendingMonth();$('#add-income').disabled=!!pendingMonth();$('#add-expense').onclick=()=>expense();$('#add-income').onclick=income;if($('#allocate'))$('#allocate').onclick=allocate;if($('#overspent-budget'))$('#overspent-budget').onclick=budgetSheet;bindGoalRows();
}
function goals(){
 $('#content').innerHTML=`<div class="topline"><h1>Ваши цели</h1>${state.goals.length?'<button id="new-goal" class="icon-button" aria-label="Добавить цель">+</button>':''}</div>${goalRows()}<div class="row"><span>Доступно для целей</span><strong>${rub(state.free)}</strong></div>${canAllocate()?'<button id="allocate">Распределить →</button>':''}`;
 if($('#new-goal'))$('#new-goal').onclick=()=>goalForm();if($('#allocate'))$('#allocate').onclick=allocate;bindGoalRows();
}
function goalDetail(){
 const g=state.goals.find(g=>g.id===selectedGoal);if(!g){goPage('goals');return;}
 const history=state.transactions.filter(t=>(t.goal_id?t.goal_id===g.id:t.goal_name===g.name)&&!t.reserve_transfer).slice().reverse();
 $('#content').innerHTML=`<div class="topline"><button class="quiet" id="goal-back">← Назад</button><button class="icon-button" id="goal-edit" aria-label="Редактировать цель">${pictogram('edit')}</button></div><div class="goal-detail"><h1>${esc(g.name)}</h1><p class="muted">${esc(goalOwner(g))}</p>${ring(g,true)}<div class="number">${rub(g.saved)}</div><p class="muted">из ${rub(g.target)}</p><p>${g.saved>=g.target?'Цель достигнута':'Осталось '+rub(g.target-g.saved)}</p>${supported('goal_metadata')?`<p class="muted">${g.deadline?`Срок: ${esc(g.deadline)}${g.deadline<dateKey()&&!g.completed?' · прошёл, измените или уберите его':''}`:'Без срока'}</p>${g.saved>=g.target||g.completed?'<button id="goal-complete">'+(g.completed?'Вернуть в активные':'Завершить цель')+'</button>':''}`:''}<button id="goal-topup" class="primary" ${canAllocate()&&!g.completed?'':'disabled'}>Пополнить</button><p class="muted">Доступно ${rub(state.free)}</p></div><h2>История цели</h2>${transactions(history)}${(state.goal_adjustments||[]).filter(e=>e.goal_id===g.id).map(e=>`<div class="row"><span>Корректировка · ${esc(e.date)}</span><span>${rub(e.before)} → ${rub(e.after)}</span></div>`).join('')}<button id="goal-spend" ${g.saved?'':'disabled'}>Расход из накоплений</button><details><summary>Приоритет цели</summary><div class="actions"><button id="goal-up" ${state.goals[0].id===g.id?'disabled':''}>Поднять</button><button id="goal-down" ${state.goals.at(-1).id===g.id?'disabled':''}>Опустить</button></div></details>`;
 for(const [id,delta] of [['goal-up',-1],['goal-down',1]])$('#'+id).onclick=async()=>{const b=$('#'+id);b.disabled=true;const ids=state.goals.map(item=>item.id),i=ids.indexOf(g.id);[ids[i],ids[i+delta]]=[ids[i+delta],ids[i]];try{await action('goal_order',{ids});}catch(e){toast(e.message);b.disabled=false;}};
 if($('#goal-complete'))$('#goal-complete').onclick=async()=>{try{await action('goal',{id:g.id,name:g.name,target:g.target,completed:!g.completed});}catch(e){toast(e.message);}};
 $('#goal-back').onclick=()=>goPage(goalOrigin);$('#goal-edit').onclick=()=>goalForm(g);$('#goal-spend').onclick=()=>goalExpense(g);
 $('#goal-topup').onclick=()=>open('Пополнить цель',`<p>${esc(g.name)} · доступно ${rub(state.free)}</p>`+amountField(),()=>action('allocate',{allocations:{[g.id]:money($('#amount').value)}}));
}
function budgetSheet(){open('Бюджет на месяц',`<p class="muted">Изменяется план расходов. Денежные остатки сохраняются.</p><label for="budget">Сумма, ₽</label><input id="budget" type="number" min="0.01" step="0.01" value="${state.budget/100}" required>`,()=>action('budget',{amount:money($('#budget').value)}));}
function settings(){
 $('#content').innerHTML=`<h1>Настройки</h1>${supported('household')?`<button class="menu-row" id="members-menu">${pictogram('heart')}<span>Участники<small>${esc(activeMember()?.name||'Выбрать участника на этом устройстве')}</small></span><span>›</span></button>`:''}<button class="menu-row" id="budget-menu">${pictogram('wallet')}<span>Бюджет на месяц<small>${rub(state.budget)}</small></span><span>›</span></button><button class="menu-row" id="categories-menu">${pictogram('categories')}<span>Категории расходов<small>${state.categories.length} категорий</small></span><span>›</span></button><button class="menu-row" id="notifications-menu">${pictogram("sun")}<span>Уведомления<small>Итоги дня и начало месяца</small></span><span>›</span></button><details class="account-options"><summary>Аккаунт и дополнительные настройки</summary><button id="account-menu">Начальные расходы и напоминания</button><button id="tutorial-menu">Как пользоваться</button><button id="logout-menu" ${window.KOPIT_DEMO?'hidden':''}>Выйти из аккаунта</button></details>`;
 if($('#members-menu'))$('#members-menu').onclick=()=>goPage('members');
 $('#notifications-menu').onclick=()=>goPage('notifications');$('#budget-menu').onclick=budgetSheet;$('#categories-menu').onclick=()=>goPage('categories');$('#account-menu').onclick=()=>goPage('account');$('#tutorial-menu').onclick=()=>goPage('tutorial');$('#logout-menu').onclick=()=>$('#logout').click();
}

function transactions(list){
 if(!list.length)return '<div class="empty">Пока тихо.<br>Запишите первый доход или расход.</div>';
 let lastDate='';return list.map(t=>{const yesterday=dateNow();yesterday.setDate(yesterday.getDate()-1);const yesterdayKey=`${yesterday.getFullYear()}-${String(yesterday.getMonth()+1).padStart(2,'0')}-${String(yesterday.getDate()).padStart(2,'0')}`;const date=t.date===dateKey()?'Сегодня':t.date===yesterdayKey?'Вчера':new Date(t.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});const heading=lastDate!==t.date?`<h3 class="history-day">${esc(date)}</h3>`:'';lastDate=t.date;
 return `${heading}<div class="row ${t.kind==='income'?'income':''}"><div><strong>${esc(t.kind==='income'?'Доход':t.kind==='expense'?t.category_name:t.kind==='allocation'?(t.reserve_transfer?'В резерв: ':'В цель: ')+t.goal_name:'Из цели: '+t.goal_name)}</strong>${members().length?`<small class="transaction-member">${esc(members().find(m=>m.id===state.household?.actors?.[t.id])?.name||'Без участника')}</small>`:''}${t.kind==='expense'&&t.tags?.length?`<div class="expense-tags" aria-label="Теги расхода">${t.tags.map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')}</div>`:''}</div><span class="sum">${t.kind==='income'?'+':t.kind==='allocation'?'+':'−'}${rub(t.amount)}</span></div>`;}).join('');
}
function categories(){$('#content').innerHTML=`<div class="topline"><h1>Расходы по категориям</h1><button class="primary" id="new-category">+ Категория</button></div><p class="muted">Лимиты: ${rub(state.categories.reduce((a,c)=>a+(c.limit||0),0))} из ${rub(state.budget)}. Категория может быть без лимита.</p><div class="card">${state.categories.length?state.categories.map(c=>{const used=state.transactions.filter(t=>t.kind==='expense'&&t.category===c.id&&t.date.startsWith(state.month)).reduce((a,t)=>a+t.amount,0);return `<div class="row"><div><h3 class="item-heading"><span class="category-mini" style="${categoryColorStyle(c)}">${pictogram(itemIcon(c))}</span>${esc(c.name)}</h3><small>${c.limit===null?'Без лимита':used>c.limit?`Лимит превышен на ${rub(used-c.limit)}`:`Осталось ${rub(c.limit-used)} из ${rub(c.limit)}`}</small><div class="tags">${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div><div><span class="sum">${rub(used)}</span><button class="quiet" data-category="${c.id}">Изменить</button>${supported('category_archive')?`<button class="quiet" data-archive-category="${esc(c.id)}">${c.archived?'Вернуть':'Архивировать'}</button>`:''}</div></div>`;}).join(''):'<div class="empty">Создайте свои категории: например, еда, жильё или машина.<br>Теги добавляются при записи расхода.</div>'}</div>`;app.querySelectorAll('[data-archive-category]').forEach(b=>b.onclick=async()=>{const c=state.categories.find(c=>c.id===b.dataset.archiveCategory);b.disabled=true;try{await action('category_archive',{id:c.id,archived:!c.archived});}catch(e){toast(e.message);b.disabled=false;}});$('#new-category').onclick=()=>categoryForm();app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>categoryForm(state.categories.find(c=>c.id===b.dataset.category)));}
function transactionHistory(){
  const months=[...new Set([state.month,...state.transactions.map(t=>t.date.slice(0,7))])].sort().reverse();
  const filters=[['','Все','Все операции за выбранный месяц'],['income','Доходы','Поступления от клиентов'],['allocation','Накопления','Пополнения целей'],['expense','Расходы','Расходы из месячного бюджета'],['goal_expense','Цели','Расходы из накоплений на цели']];
  let kind='';
  $('#content').innerHTML=`<div class="topline"><h1>История</h1></div><div class="history-filters"><select id="history-month" aria-label="Месяц истории">${months.map(m=>`<option>${m}</option>`).join('')}</select>${members().length?`<select id="history-member" aria-label="Участник истории"><option value="">Все участники</option><option value="unassigned">Без участника</option>${members().map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select>`:''}</div><div class="history-totals"><div><span class="muted">Расходы</span><strong id="history-expense-sum"></strong></div><div><span class="muted">Доходы</span><strong id="history-income-sum"></strong></div></div><p id="history-opening-note" class="muted"></p><section class="spending-statistics"><div class="section-title"><h2>Статистика расходов</h2><select id="stats-period" aria-label="Период статистики"><option value="month">Месяц</option><option value="week">Неделя</option><option value="year">Год</option></select></div><p id="stats-range" class="muted"></p><strong id="stats-total" class="number"></strong><div id="stats-categories"></div><p id="stats-note" class="muted"></p></section><div class="history-tabs" role="tablist" aria-label="Виды операций">${filters.map(([id,name],i)=>`<button id="history-tab-${i}" type="button" role="tab" data-history-kind="${id}" aria-selected="${i===0}" aria-controls="history-list" tabindex="${i===0?0:-1}">${name}</button>`).join('')}</div><div class="history-summary"><p id="history-description"></p><strong id="history-total"></strong></div><div class="card" id="history-list" role="tabpanel" aria-labelledby="history-tab-0"></div>`;
  const update=()=>{
    const list=state.transactions.filter(t=>t.date.startsWith($('#history-month').value)&&actorMatches(t)&&(!kind||t.kind===kind)).reverse();
    const month=$('#history-month').value,all=state.transactions.filter(t=>t.date.startsWith(month)&&actorMatches(t));
    $('#history-expense-sum').textContent=rub(all.filter(t=>t.kind==='expense').reduce((a,t)=>a+t.amount,0)+((!$('#history-member')?.value||$('#history-member')?.value==='unassigned')&&state.opening?.month===month?state.opening.spent:0));
    const opening=(!$('#history-member')?.value||$('#history-member')?.value==='unassigned')&&state.opening?.month===month?state.opening.spent:0;$('#history-opening-note').textContent=opening?`В расходах учтено ${rub(opening)} до начала подробных записей.`:'';
    $('#history-income-sum').textContent=rub(all.filter(t=>t.kind==='income').reduce((a,t)=>a+t.amount,0));
    $('#history-list').innerHTML=transactions(list.slice().sort((a,b)=>b.date.localeCompare(a.date)));if(supported('history_edit')){const rows=[...$('#history-list').querySelectorAll('.row')];const ordered=list.slice().sort((a,b)=>b.date.localeCompare(a.date));rows.forEach((row,i)=>{const t=ordered[i];if(!['income','expense'].includes(t.kind))return;const b=document.createElement('button');b.className='quiet';b.textContent='Изменить';b.setAttribute('aria-label','Изменить '+(t.kind==='income'?'доход':'расход')+' '+rub(t.amount));b.onclick=()=>editTransaction(t);row.append(b);});const deleted=(state.transaction_audit||[]).filter(e=>e.kind==='transaction_delete'&&!e.restored&&e.transaction.date.startsWith(state.month)).at(-1);if(deleted){const b=document.createElement('button');b.textContent='Отменить последнее удаление';b.onclick=async()=>{try{await action('transaction_restore',{audit_id:deleted.id});}catch(e){toast(e.message);}};$('#history-list').prepend(b);}}
    $('#history-description').textContent=filters.find(f=>f[0]===kind)[2];
    $('#history-total').textContent=kind?rub(list.reduce((a,t)=>a+t.amount,0)):`${list.length} записей`;
    app.querySelectorAll('[data-history-kind]').forEach((b,i)=>{const active=b.dataset.historyKind===kind;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active)$('#history-list').setAttribute('aria-labelledby',`history-tab-${i}`);});
  };
  const tabs=[...app.querySelectorAll('[data-history-kind]')];
  tabs.forEach((b,i)=>{
    b.onclick=()=>{kind=b.dataset.historyKind;update();};
    b.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();tabs[next].click();tabs[next].focus();};
  });
  if($('#history-member'))$('#history-member').onchange=()=>{update();spendingStatistics();};
 $('#history-month').onchange=()=>{update();spendingStatistics();};$('#stats-period').onchange=spendingStatistics;update();spendingStatistics();
}
function accountSettings(){$('#content').innerHTML=`<div class="settings"><h1>Ваши правила</h1><section class="card"><h2>Зарплата самому себе</h2><p class="muted">Изменяется план. Денежные остатки и история сохраняются, обеспеченность зарплат пересчитывается.</p><form id="budget-form"><label for="budget">Сумма, ₽</label><input id="budget" type="number" min="1" step="0.01" value="${state.budget/100}" required><div class="form-actions"><button class="primary">Сохранить бюджет</button></div></form></section><section class="card"><h2>Расходы до начала учёта</h2><p class="muted">Осталось без подробных записей: ${rub(state.opening?.month===state.month?state.opening.spent:0)}. Подробная запись заменяет часть этой суммы без повторного списания.</p><button id="opening-edit">Указать или исправить сумму</button><button id="opening-details" ${(state.opening?.month===state.month?state.opening.spent:0)>0?'':'disabled'}>Заменить часть подробной записью</button></section><section class="card"><h2>Меню</h2><label><input id="icons-only" type="checkbox" ${state.appearance?.icons_only?'checked':''}>Только пиктограммы, без подписей</label><p class="muted">Подписи помогают освоиться. Можно оставить только значки, когда привыкнете.</p></section><section class="card"><h2>Аккаунт</h2><p>${esc(email)}</p><p class="muted">Валюта — рубли. Финансовый день — по московскому времени. ${window.KOPIT_DEMO?'Это демонстрация. Данные не сохраняются и не отправляются на сервер.':'Данные хранятся на сервере; входите в этот аккаунт с других устройств.'}</p><button id="export">Скачать свои данные</button></section></div>`;$('#opening-details').onclick=()=>expense(true);$('#opening-edit').onclick=()=>open('Начальные расходы',`<p>Укажите общую сумму расходов до начала учёта за текущий месяц. Коррекция изменит остаток на разницу; существующие подробные записи сохранятся.</p><label for="opening-amount">Сумма, ₽</label><input id="opening-amount" type="number" min="0" step="0.01" value="${(state.opening?.month===state.month?state.opening.spent:0)/100}" required>`,()=>action('opening_set',{amount:money($('#opening-amount').value)}));$('#budget-form').onsubmit=async e=>{e.preventDefault();try{await action('budget',{amount:money($('#budget').value)});toast('Бюджет сохранён');}catch(err){toast(err.message);}};$('#icons-only').onchange=async()=>{try{await action('appearance',{icons_only:$('#icons-only').checked});}catch(err){toast(err.message);}};$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`kopit-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
function open(title,html,submit){
  const opener=document.activeElement?.id;
  modal.addEventListener('close',()=>{if(!modal.open&&opener)document.getElementById(opener)?.focus({preventScroll:true});},{once:true});
  $('#modal-title').textContent=title;
  const error=$('#modal-error');error.textContent='';
  modal.append(error);
  $('#modal-body').innerHTML=`<form id="modal-form" novalidate>${html}<div id="modal-feedback"></div><div class="form-actions"><button type="button" id="cancel">Отмена</button><button type="submit" class="primary" id="submit-modal">Сохранить</button></div></form>`;
  $('#modal-feedback').append(error);
  const form=$('#modal-form'),button=$('#submit-modal');
  $('#cancel').onclick=()=>modal.close();
  form.addEventListener('click',e=>{const group=e.target.closest('[data-icon-group]');if(group){form.querySelectorAll('[data-icon-panel]').forEach(el=>el.hidden=el.dataset.iconPanel!==group.dataset.iconGroup);form.querySelectorAll('[data-icon-group]').forEach(el=>el.setAttribute('aria-pressed',String(el===group)));return;}const picked=e.target.closest('[data-icon-choice]');if(!picked)return;$('#icon-choice').value=picked.dataset.iconChoice;form.querySelectorAll('[data-icon-choice]').forEach(b=>{const selected=b===picked;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});});
  form.addEventListener('input' ,()=>{error.textContent='';});
  form.onsubmit=async e=>{
    e.preventDefault();if(button.disabled)return;
    const invalid=[...form.querySelectorAll('input,select')].find(input=>!input.validity.valid);
    if(invalid){error.textContent=invalid.validity.valueMissing?'Заполните обязательное поле.':'Проверьте введённое значение: '+invalid.validationMessage;invalid.focus();return;}
    button.disabled=true;
    try{await submit();modal.close();toast('Сохранено');}
    catch(err){error.textContent=err.message;button.disabled=false;error.scrollIntoView({block:'nearest'});}
  };
  modal.showModal();requestAnimationFrame(fitVisibleViewport);
}
