function canAllocate(){return state.balance>=0&&state.free>0&&state.reserve>=state.budget&&state.balance+monthSpent()>=state.budget;}
function allocate(){
 if(pageFlow?.kind==='allocation')return;
 if(!canAllocate()){toast('Сначала обеспечьте текущий и следующий месяц.');return;}
 const goals=[...state.goals.filter(g=>!g.completed).map(g=>({...g})),{id:'salary-reserve-ui',name:'Резерв будущих зарплат',reserve_target:true}],total=state.free;let saving=false;
 openPage('allocation','Распределить деньги',`<p class="muted">Доступно ${rub(total)}. Шаг ползунка — 500 ₽. Остаток меньше 500 ₽ отправим в резерв при сохранении.</p>${goals.map((g,i)=>`<div class="allocation-item"><label for="alloc-${i}">${esc(g.name)}</label><input id="alloc-${i}" class="allocation" data-index="${i}" aria-label="Сумма для ${esc(g.name)}" inputmode="decimal" type="text" maxlength="32" value="0" required><input class="allocation-slider" data-index="${i}" type="range" min="0" max="${total}" step="50000" value="0" aria-label="Распределить в ${esc(g.name)}"></div>`).join('')}<div class="row"><span>Останется свободно</span><strong id="allocation-left">${rub(total)}</strong></div><p id="allocation-remainder" class="muted" role="status"></p>`,()=>{
  if(saving)return;const values=read();const allocations={};let reserve_amount=0;goals.forEach((g,i)=>{if(g.reserve_target)reserve_amount=values[i];else allocations[g.id]=values[i];});const left=total-values.reduce((a,v)=>a+v,0);if(left>0&&left<50000)reserve_amount+=left;saving=true;inputs.forEach(i=>i.readOnly=true);sliders.forEach(i=>i.disabled=true);return action('allocate',{allocations,reserve_amount}).catch(e=>{saving=false;inputs.forEach(i=>i.readOnly=false);sliders.forEach(i=>i.disabled=false);throw e;});
 });
 const root=$('#page-form')||modal,saveButton=$('#flow-submit')||$('#submit-modal'),errorNode=$('#flow-error')||$('#modal-error');
 const inputs=[...root.querySelectorAll('.allocation')],sliders=[...root.querySelectorAll('.allocation-slider')];
 function read(){const values=inputs.map(i=>money(i.value)),used=values.reduce((a,v)=>a+v,0);if(!Number.isSafeInteger(used)||used>total)throw Error('Сумма превышает доступные деньги. Уменьшите распределение.');return values;}
 function update(){if(saving)return;try{
  const values=read(),used=values.reduce((a,v)=>a+v,0),left=total-used,automatic=left>0&&left<50000?left:0;
  $('#allocation-left').textContent=rub(left-automatic);$('#allocation-remainder').textContent=automatic?`${rub(automatic)} дополнительно в резерв будущих зарплат`:'';
  sliders.forEach((slider,i)=>{const available=total-used+values[i];slider.max=Math.floor(available/50000)*50000;slider.value=Math.floor(values[i]/50000)*50000;slider.disabled=Number(slider.max)===0;});
  errorNode.textContent='';saveButton.disabled=false;
 }catch(e){errorNode.textContent=e.message;saveButton.disabled=true;sliders.forEach(slider=>slider.disabled=true);}}
 inputs.forEach(input=>input.oninput=update);
 sliders.forEach((slider,i)=>slider.oninput=()=>{
  if(saving)return;
  try{const values=read(),available=total-values.reduce((sum,v,j)=>sum+(j===i?0:v),0),maximum=Math.floor(available/50000)*50000;const value=Math.max(0,Math.min(maximum,Math.floor(Number(slider.value)/50000)*50000));inputs[i].value=value/100;update();}catch{update();}
 });update();
}
function dailyFlow(){
 if(!ensureMember())return;
 if(pageFlow?.kind==='daily')return;
 if(pendingMonth()){toast('Сначала завершите предыдущий месяц.');return;}
 const categories=state.categories.filter(c=>!c.archived);
 if(!categories.length){categoryForm(null,()=>dailyFlow());return;}
 openPage('daily','Как прошёл день?',memberNote()+`<p class="muted">Добавьте расходы, которые ещё не записаны. Уже сохранённые суммы повторно вводить не нужно.</p><label for="daily-date">Дата</label><input id="daily-date" type="date" min="${state.month}-01" max="${dateKey()}" value="${dateKey()}" required><p class="muted" id="daily-recorded"></p><div id="daily-entries"></div><button type="button" id="daily-add" class="secondary">+ Добавить расход</button><div class="row"><span>Новые расходы</span><strong id="daily-total">0 ₽</strong></div><button type="button" class="quiet" id="daily-zero">Сегодня без расходов</button>`,()=>{const entries=readDaily();if(!entries.length)throw Error('Введите сумму хотя бы для одной категории или отметьте день без расходов.');return action('daily_expenses',{date:$('#daily-date').value,entries});});
 dateTiles('daily-date');
 $('#flow-submit').textContent='Сохранить расходы';
 function readDaily(){return [...$('#daily-entries').children].map(row=>({category:$('select',row).value,amount:$('input',row).value.trim()?money($('input',row).value):0,tags:row.readTags?row.readTags():[]})).filter(e=>e.amount>0).map(e=>{if(!e.category)throw Error('Выберите категорию для каждого расхода.');return e;});}
 const update=()=>{const date=$('#daily-date').value,records=state.transactions.filter(t=>t.kind==='expense'&&t.date===date),spent=records.reduce((a,t)=>a+t.amount,0);$('#daily-recorded').textContent='Уже записано за день: '+rub(spent);$('#daily-zero').hidden=spent>0;$('#daily-zero').textContent=date===dateKey()?'Сегодня без расходов':'День без расходов';for(const row of $('#daily-entries').children){const used=records.filter(t=>t.category===$('select',row).value).reduce((a,t)=>a+t.amount,0);$('.daily-existing',row).textContent=used?'Уже записано '+rub(used):'';}try{$('#daily-total').textContent=rub(readDaily().reduce((a,e)=>a+e.amount,0));$('#flow-error').textContent='';}catch(e){$('#daily-total').textContent='Проверьте суммы';$('#flow-error').textContent=e.message;}};
 let entryIndex=0;
 $('#daily-add').onclick=()=>{const i=entryIndex++,row=document.createElement('div');row.className='daily-amount-row';row.innerHTML=`<div><label for="daily-category-${i}">Категория</label><select id="daily-category-${i}" required><option value="">Выберите категорию</option>${categories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><small class="daily-existing"></small></div><div><label for="daily-amount-${i}">Сумма, ₽</label><input id="daily-amount-${i}" type="text" inputmode="decimal" maxlength="32" autocomplete="off" placeholder="0" required></div><button type="button" class="quiet daily-remove" aria-label="Убрать расход">Убрать</button>`;row.querySelector('button').onclick=()=>{row.remove();update();};$('#daily-entries').append(row);categoryTiles($('select',row));const tags=document.createElement('details');tags.className='daily-tags';tags.innerHTML='<summary>Теги — по желанию</summary><div></div>';row.append(tags);row.readTags=tagPicker(tags.querySelector('div'));update();};
 $('#daily-date').onchange=update;$('#daily-entries').addEventListener('input',update);$('#daily-entries').addEventListener('change',update);
 $('#daily-zero').onclick=async()=>{let entries;try{entries=readDaily();}catch(e){$('#flow-error').textContent=e.message;return;}if(entries.length){$('#flow-error').textContent='Сначала очистите новые расходы, чтобы отметить день без расходов.';return;}const b=$('#daily-zero');if(b.disabled)return;const origin=pageFlow.origin;b.disabled=true;$('#flow-submit').disabled=true;setFlowBusy(true);try{await action('daily_expenses',{date:$('#daily-date').value,entries:[]});goPage(origin);toast('День отмечен без расходов');}catch(e){if(!$('#page-form'))return;$('#flow-error').textContent=e.message;b.disabled=false;$('#flow-submit').disabled=false;setFlowBusy(false);}};update();
}

const pushStorageKey=()=>`kopit-push:${location.pathname}:${email}`;
function pushLocal(suffix,value){try{const key=pushStorageKey()+':'+suffix;if(value===undefined)return localStorage.getItem(key);value===null?localStorage.removeItem(key):localStorage.setItem(key,value);}catch{}return null;}
function pushSupported(){return window.isSecureContext&&'serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window;}
async function pushRegistration(){return navigator.serviceWorker.getRegistration(new URL('./',location.href).href);}
async function enablePush(){
 if(!pushSupported())throw Error('В этом браузере push недоступен. На iPhone добавьте Копит на экран «Домой» и откройте оттуда.');
 // Call permission synchronously from the user's click, before network requests.
 const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();
 if(permission!=='granted')throw Error(permission==='denied'?'Уведомления запрещены в настройках браузера. Разрешите их для этого сайта.':'Разрешение не получено. Можно включить уведомления позже.');
 const configuration=await api('push_key',{});
 if(!configuration?.available||!configuration.public_key)throw Error('Сервер уведомлений ещё не подключён. Попробуйте позже.');
 await navigator.serviceWorker.register('./notification-worker.js',{scope:'./'});
 const registration=await navigator.serviceWorker.ready;
 const bytes=Uint8Array.from(atob(configuration.public_key.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
 const subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});
 await api('push_subscribe',{subscription:subscription.toJSON()});
 const daily=$('#notify-time')?.value||state.reminders.daily||'21:00';
 await action('reminders',{enabled:true,daily,day:1});
 pushLocal('enabled','1');pushLocal('dismissed',null);goPage('notifications');toast('Уведомления включены на этом устройстве');
}
async function disablePush(){
 const registration=await pushRegistration(),subscription=await registration?.pushManager.getSubscription();
 if(subscription){await api('push_unsubscribe',{endpoint:subscription.endpoint});await subscription.unsubscribe();}
 pushLocal('enabled',null);goPage('notifications');toast('Уведомления на этом устройстве отключены');
}
function notificationSettings(){
 const supported=pushSupported(),enabled=pushLocal('enabled')==='1'&&supported&&Notification.permission==='granted';
 $('#content').innerHTML=`<h1>Уведомления</h1><p class="muted">Напоминания приходят и при закрытом Копит. Интернет и разрешение браузера необходимы; время — московское.</p><section class="card"><h2>Как прошёл день?</h2><p>Вечером предложим записать расходы и проверить, на что вы потратили сегодня. Нажатие откроет дневник.</p><label for="notify-time">Время итогов дня</label><input id="notify-time" type="time" required value="${esc(state.reminders.daily||'21:00')}"></section><section class="card"><h2>Начало месяца</h2><p>Первого числа в 09:00 напомним завершить предыдущий месяц и распределить свободные деньги по целям или в резерв. Остатки меняются только после вашего подтверждения в приложении.</p></section><p class="note">На iPhone: Safari → Поделиться → На экран «Домой». Откройте Копит с появившейся иконки и нажмите «Включить».</p><p id="push-status" role="status">${enabled?'Включены на этом устройстве':supported?'На этом устройстве пока не включены':'В этом браузере push недоступен. Используйте поддерживаемый браузер или приложение с экрана «Домой».'}</p><p id="push-error" role="alert"></p><div class="notification-actions"><button id="push-enable" class="primary" ${enabled||!supported?'hidden':''}>Включить уведомления</button><button id="push-save" class="primary" ${enabled?'':'hidden'}>Сохранить время</button><button id="push-disable" ${enabled?'':'hidden'}>Отключить на этом устройстве</button></div><p class="muted">Суммы и категории не показываются на экране блокировки. Отправляем напоминание, а подробности открываются внутри аккаунта.</p>`;
 const run=fn=>async()=>{const time=$('#notify-time');if(!time.reportValidity())return;const buttons=[...document.querySelectorAll('.notification-actions button')];buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){if($('#push-error'))$('#push-error').textContent=e.message;buttons.forEach(b=>b.disabled=false);}};
 $('#push-enable').onclick=run(enablePush);$('#push-disable').onclick=run(disablePush);
 $('#push-save').onclick=run(async()=>{const daily=$('#notify-time').value;await action('reminders',{enabled:true,daily,day:1});toast('Время уведомлений сохранено');});
}
let reminderIntent=new URLSearchParams(location.search).get('reminder');
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='kopit-reminder'&&['daily','monthly'].includes(event.data.kind)){reminderIntent=event.data.kind;remind();}});
function remind(){
 if(!state||needsSetup())return;
 if(reminderIntent){const kind=reminderIntent;reminderIntent=null;const url=new URL(location.href);url.searchParams.delete('reminder');window.history.replaceState(null,'',url);if(pageFlow||modal.open){toast('Завершите открытую форму. Затем откройте дневник или цели.');return;}if(kind==='monthly'||pendingMonth()){goPage(pendingMonth()?'closing':'goals');return;}if(kind==='daily'){dailyFlow();return;}}
 if(page==='home'&&!pageFlow&&!$('#notification-invite')&&!pushLocal('dismissed')&&pushLocal('enabled')!=='1'){
  $('#content')?.insertAdjacentHTML('beforeend','<section id="notification-invite" class="note"><h2>Напомнить об итогах дня?</h2><p>Вечером — расходы за день. Первого числа — завершение месяца и распределение денег.</p><div class="actions"><button id="notification-open">Настроить уведомления</button><button id="notification-later" class="quiet">Позже</button></div></section>');
  $('#notification-open').onclick=()=>goPage('notifications');$('#notification-later').onclick=()=>{pushLocal('dismissed','1');$('#notification-invite').remove();};
 }
}

modal.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const elements=[...modal.querySelectorAll('button,input,select,textarea,a[href],[tabindex]')].filter(el=>!el.disabled&&el.tabIndex>=0&&el.getClientRects().length);const first=elements[0],last=elements.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
$('#close-modal').onclick=()=>modal.close();$('#logout').onclick=async()=>{try{await api('logout',{});auth();}catch(e){toast(e.message);}};
setInterval(async()=>{if(!window.KOPIT_DEMO&&state&&!needsSetup()&&!modal.open&&!$('input:focus')&&!$('select:focus')){try{const next=await api('state');if(next.revision!==revision||(next.server_date&&next.server_date!==serverDay)||renderedDay!==dateKey()){accept(next);render();}}catch{}}remind();},15000);
// One question per screen; the complete draft is committed in a single action.
let setupDraft=null,setupStage='welcome',setupBack=[],setupSaving=false;
function needsSetup(){return state&&state.onboarding_complete!==true&&!state.transactions.length&&!state.categories.length&&!state.balance&&!state.reserve&&!state.free&&!state.goals.some(g=>g.saved||!g.reserve);}
function startSetup(){
 setupDraft={budget:17500000,total:0,balance:0,spent:0,reserve:0,goals:[],categories:[],goalName:'',goalTarget:0,goalSaved:0,categoryName:'',categoryLimit:null};setupStage='budget';setupBack=[];drawSetup();
}
function drawSetup(){
 const d=setupDraft,stage=setupStage;
 const next=(target)=>{setupBack.push(stage);setupStage=target;drawSetup();window.scrollTo(0,0);};
 const field=(label,value,placeholder='0')=>`<label for="setup-value">${label}</label><input id="setup-value" type="text" inputmode="decimal" autocomplete="off" value="${value===null?'':esc(value/100)}" placeholder="${placeholder}">`;
 const nameField=(label,value)=>`<label for="setup-name">${label}</label><input id="setup-name" type="text" maxlength="60" autocomplete="off" value="${esc(value)}" required>`;
 let heading='',copy='',body='',button='Далее',extra='';
 const sections={welcome:1,budget:1,total:2,balance:2,spent:2,reserve:2,goals:3,goalName:3,goalTarget:3,goalSaved:3,categories:4,categoryName:4,categoryLimit:4,review:5};
 if(stage==='welcome'){heading='Настроим ваш бюджет';copy='Ответьте на несколько вопросов: сколько вы планируете тратить, какие суммы уже есть, на что копите и куда обычно тратите. На каждом экране — один шаг.';body='<p>Введённые данные сохранятся после проверки в конце. Если закрыть страницу раньше, настройку нужно будет начать заново.</p>';button='Начать';}
 if(stage==='budget'){heading='Какая планируемая сумма трат за месяц?';copy='Это ваша зарплата самому себе. План не создаёт деньги: дальше подтвердим фактические начальные остатки.';body=field('Зарплата на месяц, ₽',d.budget)+`<p id="salary-preview">Зарплата на месяц — ${rub(d.budget)}</p>`;}
 if(stage==='total'){heading='Сколько денег у вас сейчас есть?';copy='Подтвердите фактическую сумму, которая уже есть. Зарплата текущего месяца предполагается выделенной, но если денег меньше — укажите реальную сумму. Укажите общую доступную сумму на текущий месяц, резерв и будущие распределения. Деньги, уже отложенные на конкретные цели, сюда не включайте: их укажем отдельно.';body=field('Доступные деньги, ₽',d.total);}
 if(stage==='balance'){heading='Сколько оставите на остаток месяца?';copy=`Это сумма для расходов с сегодняшнего дня до конца месяца. Доступно ${rub(d.total)}, месячный бюджет ${rub(d.budget)}.`;body=field('Остаток на месяц, ₽',d.balance);}
 if(stage==='spent'){heading='Сколько уже потратили в этом месяце?';copy='Необязательно. Можно пропустить и заполнить позже в настройках. Подробные записи смогут заменить эту сумму без двойного учёта.';body=field('Уже потрачено, ₽',d.spent);extra='<button type="button" id="skip-spent">Пропустить</button>';}
 if(stage==='reserve'){heading='Сколько отложите на следующий месяц?';copy=`После текущего остатка осталось ${rub(d.total-d.balance)}. Резерв может содержать несколько зарплат. Укажите деньги, которые уже есть; не включайте накопления целей повторно.`;body=field('Резерв будущих зарплат, ₽',d.reserve);}
 if(stage==='goals'){heading='На что ещё хотите накопить?';copy='Добавьте свои цели по одной. Для каждой укажем нужную сумму и то, что уже накоплено. Можно продолжить без дополнительных целей.';body=`<div class="setup-list">${d.goals.map((g,i)=>`<div class="row"><div><strong>${esc(g.name)}</strong><small>${rub(g.saved)} из ${rub(g.target)}${g.completed?" · Завершена":""}</small></div><button type="button" class="quiet" data-remove-goal="${i}" aria-label="Удалить цель ${esc(g.name)}">Убрать</button></div>`).join('')}</div>`;extra='<button type="button" id="setup-add-goal">+ Добавить цель</button>';}
 if(stage==='goalName'){heading='Как называется цель?';copy='Например, отпуск или новый ноутбук.';body=nameField('Название цели',d.goalName);}
 if(stage==='goalTarget'){heading='Сколько нужно накопить?';copy=`Цель: ${d.goalName}.`;body=field('Сумма цели, ₽',d.goalTarget);}
 if(stage==='goalSaved'){heading='Сколько уже накоплено на эту цель?';copy=`Цель: ${d.goalName}. Эти накопления должны быть отдельными от общей доступной суммы, указанной раньше.`;body=field('Уже накоплено, ₽',d.goalSaved);button='Добавить цель';}
 if(stage==='categories'){heading='На что обычно тратите?';copy='Добавьте основные категории по одной. Можно продолжить без категорий и создать их позже.';body=`<div class="setup-list">${d.categories.map((c,i)=>`<div class="row"><div><strong>${esc(c.name)}</strong><small>${c.limit===null?'Без лимита':'Лимит '+rub(c.limit)}</small></div><button type="button" class="quiet" data-remove-category="${i}" aria-label="Удалить категорию ${esc(c.name)}">Убрать</button></div>`).join('')||'<p class="muted">Пока нет категорий.</p>'}</div>`;extra='<button type="button" id="setup-add-category">+ Добавить категорию</button>';}
 if(stage==='categoryName'){heading='Как назвать категорию?';copy='Например, еда, жильё или машина.';body=nameField('Название категории',d.categoryName);}
 if(stage==='categoryLimit'){heading='Нужен лимит для этой категории?';copy=`Категория: ${d.categoryName}. Сумма всех лимитов не должна превышать ${rub(d.budget)}. Можно оставить поле пустым.`;body=field('Месячный лимит, ₽ — необязательно',d.categoryLimit,'Без лимита');button='Добавить категорию';}
 if(stage==='review'){
  heading='Проверьте начальные данные';copy='Это стартовые остатки, а не новые поступления или расходы. После сохранения можно записывать обычные операции.';button='Сохранить и начать';
  body=`<dl class="setup-summary"><dt>Бюджет месяца</dt><dd>${rub(d.budget)}</dd><dt>Осталось на месяц</dt><dd>${rub(d.balance)}</dd><dt>Уже потрачено</dt><dd>${rub(d.spent)}</dd><dt>Резерв будущих зарплат</dt><dd>${rub(d.reserve)}</dd><dt>Для распределения по целям</dt><dd>${rub(d.total-d.balance-d.reserve)}</dd><dt>Уже накоплено в целях</dt><dd>${rub(d.goals.reduce((s,g)=>s+g.saved,0))}</dd><dt>Всего денег с накоплениями</dt><dd>${rub(d.total+d.goals.reduce((s,g)=>s+g.saved,0))}</dd></dl><p><strong>Цели:</strong> ${d.goals.map(g=>esc(g.name)).join(', ')||'пока не добавлены'}.</p><p><strong>Категории:</strong> ${d.categories.map(c=>esc(c.name)+(c.limit===null?' (без лимита)':' ('+rub(c.limit)+')')).join(', ')||'пока не добавлены'}.</p>${d.reserve<d.budget||d.balance+d.spent<d.budget?'<div class="note">Распределение новых денег по целям станет доступно, когда обеспечены бюджет текущего месяца и резерв на следующий.</div>':''}`;
 }
 app.innerHTML=`<section class="setup" aria-label="Первоначальная настройка"><div class="eyebrow">Начало работы · ${sections[stage]} / 5</div><progress class="setup-progress" max="5" value="${sections[stage]}" aria-label="Этап ${sections[stage]} из 5"></progress><h1 tabindex="-1">${esc(heading)}</h1><p class="setup-copy">${esc(copy)}</p><form id="setup-form" novalidate>${body}<p id="setup-error" role="alert"></p><div class="setup-actions">${extra}<button type="submit" class="primary" id="setup-next">${button}</button>${setupBack.length?'<button type="button" class="quiet" id="setup-back">Назад</button>':''}</div></form><p class="muted setup-save-note">Сохраним все ответы после кнопки «Сохранить и начать».</p></section>`;
 if($('#salary-preview'))$('#setup-value').oninput=()=>{try{$('#salary-preview').textContent='Зарплата на месяц — '+rub(money($('#setup-value').value));}catch{$('#salary-preview').textContent='Введите плановую сумму';}};
 if($('#skip-spent'))$('#skip-spent').onclick=()=>{d.spent=0;d.total=d.budget;next('total');};
 $('h1',app).focus({preventScroll:true});
 if($('#setup-back'))$('#setup-back').onclick=()=>{if(setupSaving)return;setupStage=setupBack.pop();drawSetup();};
 if($('#setup-add-goal'))$('#setup-add-goal').onclick=()=>{d.goalName='';d.goalTarget=0;d.goalSaved=0;next('goalName');};
 if($('#setup-add-category'))$('#setup-add-category').onclick=()=>{d.categoryName='';d.categoryLimit=null;next('categoryName');};
 for(const type of ['goal','category'])app.querySelectorAll(`[data-remove-${type}]`).forEach(b=>b.onclick=()=>{d[type==='goal'?'goals':'categories'].splice(Number(b.dataset[type==='goal'?'removeGoal':'removeCategory']),1);drawSetup();});
 $('#setup-form').onsubmit=async e=>{
  e.preventDefault();if(setupSaving)return;
  try{
   const value=()=>{const n=money($('#setup-value').value);if(n>100000000000)throw Error('Укажите сумму не больше 1 000 000 000 ₽.');return n;};
   const name=()=>{const n=$('#setup-name').value.trim();if(!n||n.length>60)throw Error('Введите название от 1 до 60 символов.');return n;};
   if(stage==='welcome')return next('budget');
   if(stage==='budget'){const n=value();if(!n)throw Error('Бюджет должен быть больше нуля.');d.budget=n;return next('spent');}
   if(stage==='total'){d.total=value();d.balance=Math.min(d.total,Math.max(0,d.budget-d.spent));return next('balance');}
   if(stage==='balance'){const n=value();if(n>d.total||n>d.budget)throw Error('Остаток не должен превышать доступные деньги или бюджет месяца.');d.balance=n;d.reserve=Math.max(0,d.total-d.balance);return next('reserve');}
   if(stage==='spent'){const n=value();d.spent=n;d.total=Math.max(0,d.budget-n);return next('total');}
   if(stage==='reserve'){const n=value();if(n>d.total-d.balance)throw Error('Резерв превышает фактическую доступную сумму.');d.reserve=n;return next('goals');}
   if(stage==='goals')return next('categories');
   if(stage==='goalName'){d.goalName=name();return next('goalTarget');}
   if(stage==='goalTarget'){const n=value();if(!n)throw Error('Сумма цели должна быть больше нуля.');d.goalTarget=n;return next('goalSaved');}
   if(stage==='goalSaved'){d.goalSaved=value();if(d.goals.length>=99)throw Error('Можно добавить не больше 99 дополнительных целей.');d.goals.push({name:d.goalName,target:d.goalTarget,saved:d.goalSaved,reserve:false,icon:itemIcon({name:d.goalName})});setupBack=setupBack.slice(0,setupBack.lastIndexOf('goals'));setupStage='goals';return drawSetup();}
   if(stage==='categories')return next('review');
   if(stage==='categoryName'){d.categoryName=name();return next('categoryLimit');}
   if(stage==='categoryLimit'){const raw=$('#setup-value').value.trim(),limit=raw===''?null:value();if(d.categories.reduce((s,c)=>s+(c.limit||0),0)+(limit||0)>d.budget)throw Error('Сумма лимитов категорий превышает бюджет месяца.');if(d.categories.length>=100)throw Error('Можно добавить не больше 100 категорий.');d.categories.push({name:d.categoryName,limit,icon:itemIcon({name:d.categoryName})});setupBack=setupBack.slice(0,setupBack.lastIndexOf('categories'));setupStage='categories';return drawSetup();}
   if(stage==='review'){
    setupSaving=true;app.querySelectorAll('button').forEach(b=>b.disabled=true);
    await action('salary_onboarding',{budget:d.budget,total:d.total,balance:d.balance,spent:d.spent,reserve:d.reserve,goals:d.goals,categories:d.categories});
    setupDraft=null;toast('Настройка сохранена. Можно записывать доходы и расходы.');
   }
  }catch(err){if(!needsSetup()){setupDraft=null;render();toast(err.message);return;}if($('#setup-error'))$('#setup-error').textContent=err.message;else toast(err.message);app.querySelectorAll('button').forEach(b=>b.disabled=false);}finally{setupSaving=false;}
 };
}

function fitVisibleViewport(){
 const v=window.visualViewport,height=v?.height||window.innerHeight,top=v?.offsetTop||0;
 document.documentElement.style.setProperty('--keyboard-gap',Math.max(0,window.innerHeight-height)+'px');document.documentElement.style.setProperty('--visual-height',height+'px');document.documentElement.style.setProperty('--visual-top',top+'px');
 const editing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'');document.body.classList.toggle('keyboard-open',editing&&height<window.innerHeight-120);
 if(modal.open){modal.style.top=Math.max(top+8,top+height-modal.getBoundingClientRect().height-8)+'px';}
 const field=document.activeElement;if(!editing||field.type==='range'||field.type==='checkbox')return;
 const r=field.getBoundingClientRect(),header=document.querySelector('.header').getBoundingClientRect(),lower=top+height-20,upper=modal.open?Math.max(top+64,$('.modal-head').getBoundingClientRect().bottom+8):Math.max(top+16,header.bottom+12);let delta=0;if(r.bottom>lower)delta=r.bottom-lower;else if(r.top<upper)delta=r.top-upper;if(delta){if(modal.open)modal.scrollTop+=delta;else window.scrollBy(0,delta);}
}
if(window.visualViewport){for(const event of ['resize','scroll'])window.visualViewport.addEventListener(event,()=>requestAnimationFrame(fitVisibleViewport));}
window.addEventListener('resize',()=>requestAnimationFrame(fitVisibleViewport));document.addEventListener('focusin',()=>requestAnimationFrame(fitVisibleViewport));document.addEventListener('focusout',()=>requestAnimationFrame(fitVisibleViewport));modal.addEventListener('close',()=>{modal.style.top='';document.body.classList.remove('keyboard-open');});fitVisibleViewport();
load();

function editTransaction(t){
 if(!t.date.startsWith(state.month)||pendingMonth()){open('Запись истории','<p>Закрытые месяцы доступны только для просмотра.</p>',async()=>{});return;}
 if(t.kind==='income'&&!t.funding){open('Доход до обновления','<p>Для исправления этого дохода нужна отдельная сверка его распределения. Накопления остаются сохранными.</p>',async()=>{});return;}
 open('Изменить '+(t.kind==='income'?'доход':'расход'),amountField(t.amount/100)+`<label for="edit-date">Дата</label><input id="edit-date" type="date" min="${state.month}-01" max="${serverDay||dateKey()}" value="${t.date}" required>${t.kind==='expense'?`<label for="edit-category">Категория</label><select id="edit-category">${state.categories.filter(c=>!c.archived||c.id===t.category).map(c=>`<option value="${esc(c.id)}" ${c.id===t.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div id="edit-tags"></div>`:''}<button type="button" id="delete-transaction" class="quiet">Удалить запись</button><p class="muted">Удаление можно отменить в истории до завершения месяца.</p>`,()=>action('transaction_edit',{id:t.id,amount:money($('#amount').value),date:$('#edit-date').value,...(t.kind==='expense'?{category:$('#edit-category').value,tags:readEditTags()}: {})}));
 dateTiles('edit-date');let readEditTags=()=>[];if(t.kind==='expense'){categoryTiles($('#edit-category'));readEditTags=tagPicker($('#edit-tags'),t.tags||[]);}
 $('#delete-transaction').onclick=async()=>{const b=$('#delete-transaction');b.disabled=true;$('#submit-modal').disabled=true;try{await action('transaction_delete',{id:t.id});modal.close();toast('Запись удалена. Отмена доступна в истории.');}catch(e){$('#modal-error').textContent=e.message;b.disabled=false;$('#submit-modal').disabled=false;}};
}
function monthClosing(){
 if(!pendingMonth()){goPage('home');return;}
 const q=closingPreview||KopitDesignRules.preview(state);
 $('#content').innerHTML=`<button class="quiet" id="closing-back">← Обзор</button><h1>Завершить месяц</h1><p>${esc(q.from_month)} → ${esc(q.to_month)}</p><div class="row"><span>Остаток переносится</span><strong>${rub(q.carry)}</strong></div><div class="row"><span>Из резерва на месяц</span><strong>${rub(q.reserve_transfer)}</strong></div><div class="row"><span>На новый месяц</span><strong>${rub(q.next_balance)}</strong></div><div class="row"><span>Резерв после перехода</span><strong>${rub(q.next_reserve)}</strong></div>${q.income<state.budget?`<p class="note">За месяц заработано ${rub(q.income)} — меньше бюджета ${rub(state.budget)}.${q.shortfall?'':' Прежние остатки покрывают новый месяц.'}</p>`:''}${q.shortfall?`<p class="note" role="status">Не хватает ${rub(q.shortfall)}. Перенесём все доступные деньги. Следующий доход сначала покроет нехватку.</p>`:''}${state.free?`<section class="closing-distribution" aria-label="Распределение перед завершением"><p>Перед завершением распределите ${rub(state.free)}.</p><div class="button-stack"><button id="closing-add-goal">Добавить цель</button>${canAllocate()?'<button id="closing-allocate">По целям или в резерв</button>':''}<button id="closing-reserve">Всё свободное в резерв</button></div></section>`:''}<div class="closing-submit"><button id="closing-confirm" class="primary" ${state.free?'disabled':''}>Завершить и перенести</button><p id="closing-error" role="alert"></p></div>`;
 $('#closing-back').onclick=()=>goPage('home');if($('#closing-add-goal'))$('#closing-add-goal').onclick=()=>goalForm();if($('#closing-allocate'))$('#closing-allocate').onclick=allocate;
 if($('#closing-reserve'))$('#closing-reserve').onclick=async()=>{try{await action('closing_reserve',{});}catch(e){$('#closing-error').textContent=e.message;}};
 $('#closing-confirm').onclick=async()=>{const b=$('#closing-confirm');b.disabled=true;try{await action('close_month',{});goPage('home');}catch(e){if($('#closing-error'))$('#closing-error').textContent=e.message;if(b.isConnected)b.disabled=false;}};
}
